
import React, { useState, useRef, useEffect } from "react";
import "./FileUpload.scss"; // Import the CSS file
import { MpaIcon } from "../icon/MpaIcon";
import LinearLoader from "../loader/LinearLoader";

export interface FileUploadProps {
  /**
   * Identifying value for the chip.
   */
  id: string;
  /**
   * Text value to be displayed next to the file upload.
   */
  label: string;
  /**
   * Progress of the file upload in percentage.
   */
  progress?: Record<string, number>;
  /**
   * Determines the colour palette of the file upload.
   */

  colour?: "primary" | "secondary" | "tertiary";
  /**
   * Text value to be displayed at file upload.
   */
  uploadMessage: string;
  /**
  * Accepted file type.
  */
  fileType: string;
  /**
  * Text value to be displayed as warning message.
  */
  warningMessage: string;
  /**
   * Maximum file size accepted in MB.
   */
  fileSize: number;
  /**
   * Tooltip text to be displayed when hovering over the help icon.
   */
  tooltip?: string;
  /**
   * Maximum file count accepted.
   */
  maxFileCount?: number;
  /**
   * File type icon shown with progress bar.
   */
  progressBarIcon?: string;
  /**
   * Custom error message shown if incorrect file type.
   */
  uploadTypeErrorMessage?: string;

  /**
   * Callback function to return valid files.
   * @param files 
   * @returns 
   */
  onFilesChange?: (files: UploadFile[]) => void;

  onInvalidFiles?: (files: UploadFile[]) => void;

  onDeleteFiles?: (file: UploadFile) => void;

  onDeleteErrorFiles?: (file: UploadFile) => void;

  /**
   * Initial/default files to display when component mounts.
   * Useful for restoring files when navigating back to a form.
   */
  defaultFiles?: UploadFile[];

  uploadSucessMessage?: string;

}

export interface UploadFile {
  file: File;
  fileId: string;
  error?: string;
  isVisible: boolean;
}

const FileUpload: React.FC<FileUploadProps> = ({
  id,
  label = "Label",
  colour = "primary",
  fileSize = 10,
  maxFileCount,
  progress,
  onFilesChange,
  onInvalidFiles,
  onDeleteFiles,
  onDeleteErrorFiles,
  defaultFiles,
  uploadMessage = "Drag and drop the file here or click here to browse",
  warningMessage = ` Only jpg, jpeg, png, doc, docx, ppt, pptx, pdf, xls, xlsx files will be supported. Each file cannot exceed ${fileSize} MB. Any special characters in file names will be removed. ${maxFileCount ? `You can upload up to ${maxFileCount} files.` : ''}`,
  fileType = "image/png,image/jpeg,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation,application/pdf,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  uploadTypeErrorMessage,
  tooltip,
  progressBarIcon,
  uploadSucessMessage,
  ...rest
}) => {

  const [selectedFiles, setSelectedFiles] = useState<UploadFile[]>(defaultFiles?.filter(f => f.isVisible && !f.error) || []);
  const [selectedErrorFiles, setSelectedErrorFiles] = useState<UploadFile[]>(defaultFiles?.filter(f => f.isVisible && f.error) || []);
  const [dragging, setDragging] = useState(false);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const [validationError, setValidationError] = useState<string>("");

  const allowedTypes = fileType.split(",");
  const maxSizeInMB = fileSize;
  const maxSizeInBytes = Number(maxSizeInMB) * 1024 * 1024;
  const visibleFileCount = useRef(defaultFiles?.filter(f => f.isVisible).length || 0);
  const fileCount = useRef(0);
  const hasInitialized = useRef(false);


  // Initialize from defaultFiles on mount
  useEffect(() => {
    if (defaultFiles && defaultFiles.length > 0 && !hasInitialized.current) {

      const validFiles = defaultFiles.filter(f => f.isVisible && !f.error);
      const errorFiles = defaultFiles.filter(f => f.isVisible && f.error);

      setSelectedFiles(validFiles);
      setSelectedErrorFiles(errorFiles);
      visibleFileCount.current = defaultFiles.filter(f => f.isVisible).length;

      // Find the highest fileId number to continue from there
      const fileIds = defaultFiles.map(f => {
        const match = f.fileId.match(/file-upload-item-(\d+)/);
        return match ? parseInt(match[1], 10) : -1;
      });
      const maxId = Math.max(...fileIds, -1);
      fileCount.current = maxId + 1;




      // Notify parent about the default files
      if (validFiles.length > 0) {
        onFilesChange?.(validFiles);
      }

      hasInitialized.current = true;
    }
  }, [defaultFiles, onFilesChange]);

  const handleClick = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click(); // Ensure ref is not null
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files || []);
    validateUploadedFiles(files);
    event.target.value = ""; // clear input value so that same file name is detected as change
  };

  const generateFileId = () => {
    let fileId = `file-upload-item-${fileCount.current}`;
    fileCount.current += 1;
    return fileId;
  }

  const validateUploadedFiles = (files: File[]) => {
    let invalidFiles: UploadFile[] = [];
    let validFiles: UploadFile[] = [];

    if (maxFileCount && (files.length + visibleFileCount.current > maxFileCount)) {
      setValidationError(`You can only upload up to ${maxFileCount} files.`);
      return;
    }
    visibleFileCount.current += files.length;
    setValidationError('');

    files.forEach((file) => {
      let item = {
        file: file,
        fileId: generateFileId(),
        isVisible: true
      } as UploadFile;

      if (!allowedTypes.includes(file.type)) {
        if (uploadTypeErrorMessage) {
          item.error = uploadTypeErrorMessage;
        } else {
          item.error = 'File type is not supported';
        }
        invalidFiles.push(item);
      } else if (file.size > maxSizeInBytes) {
        item.error = `File is too large (max. ${fileSize} MB)`;
        invalidFiles.push(item);
      } else {
        validFiles.push(item);
      }
    });

    if (invalidFiles.length > 0) {
      setSelectedErrorFiles((prev) => [...prev, ...invalidFiles]);
      onInvalidFiles?.(invalidFiles);

    }
    if (validFiles.length > 0) {
      setSelectedFiles((prev) => [...prev, ...validFiles]);
      onFilesChange?.([...selectedFiles.filter((item) => item.isVisible), ...validFiles]);

    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragging(true);
  };

  const handleDragLeave = () => {
    setDragging(false);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragging(false);
    const files = Array.from(event.dataTransfer.files); // Extract dropped files

    validateUploadedFiles(files);
  };

  const handleDelete = (index: number) => {
    setSelectedFiles(prev => {
      const deletedFile = prev[index];
      const updated = prev.filter((_, i) => i !== index);

      onFilesChange?.(updated);
      onDeleteFiles?.(deletedFile);

      return updated;
    });

    visibleFileCount.current--;
    setValidationError('');
  };

  const handleDeleteErrorFile = (index: number) => {

    setSelectedErrorFiles(prev => {
      const deletedFile = prev[index];
      const updated = prev.filter((_, i) => i !== index);

      onInvalidFiles?.(updated);
      onDeleteErrorFiles?.(deletedFile);

      return updated;
    });

    visibleFileCount.current--;
    setValidationError('');
  };


  // const handleUpload = () => {
  //   if (!selectedFiles) {
  //     alert("No file selected");
  //     return;
  //   }

  //   const formData = new FormData();
  //   Array.from(selectedFiles).forEach((item) => {
  //     formData.append("files", item.file);
  //   });

  //   fetch("YOUR_UPLOAD_ENDPOINT", {
  //     method: "POST",
  //     body: formData,
  //   })
  //     .then((response) => response.json())
  //     .then((data) => console.log("Success:", data))
  //     .catch((error) => console.error("Error:", error));    
  // };

  const loaderColour = `var(--mpa-fileupload-${colour}-color)`;

  return (
    <div>
      <div className="label-icon-container">
        <span className="label-text">{label}</span>
        {
          tooltip &&
          <MpaIcon iconName="Help" colour="var(--mpa-gray)" tooltipText={tooltip} />
        }
      </div>
      <div className={`upload-container ${colour}-container ${dragging ? "dragging" : ""}`}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <div
          className={`drop-zone `}

        >
          <p className="upload-text">
            <span className={`upload-link ${colour}-fileUpload upload-link-flex`}>
              {<MpaIcon iconName="CloudUpload" />}
              <span onClick={handleClick}>{uploadMessage}</span>
            </span>
          </p>
          <input type="file" multiple onChange={handleFileChange} ref={fileInputRef} />
        </div>

        <p className="file-info">
          {warningMessage}
        </p>
      </div>

      {
        validationError && <div className="label-icon-container label-adjust">
          <span className="help-icon error">
            {<MpaIcon iconName="AlertCircle" size={18} />}
          </span>
          <span className="label-text error">{validationError}</span>
        </div>
      }

      {selectedErrorFiles && (selectedErrorFiles.map((item, index) => (
        item.isVisible && (
          <>
            <div className="upload-card error" key={item.fileId}>
              <div className="upload-info">
                <div className="file-icon error-bg error-file-colour">
                  <MpaIcon iconName={progressBarIcon ? progressBarIcon : "FilePdf_SGDS"} />
                </div>
                <div className="file-details">
                  <div className="file-name error">{item.file.name}</div>
                  <div className="file-name error">
                    {(item.file.size / (1024 * 1024)).toFixed(2)}MB <span className="file-meta-separator">&nbsp; &bull; &nbsp;</span>  Upload Failed
                  </div>
                </div>
                <div className="delete-icon" onClick={() => handleDeleteErrorFile(index)}>
                  {<MpaIcon iconName="Trash" size={20} />}
                </div>
              </div>
              <div className="progress-bar-file">
                <LinearLoader id={`linear_loader_${item.fileId}`} colour="var(--mpa-red)" progress={25} showProgress={false} bar_width="100%"></LinearLoader>
              </div>
            </div>
            <div className="label-icon-container label-adjust">
              <span className="help-icon error">
                {<MpaIcon iconName="AlertCircle" size={18} />}
              </span>
              <span className="label-text error">{item.error}</span>
            </div>

          </>

        ))))}
      {selectedFiles && selectedFiles.map((item, index) => (
        item.isVisible && ( // Only render if the file is visible
          <div className={`upload-card`} key={item.fileId}>
            <div className="upload-info">
              <div className="file-icon">
                {<MpaIcon iconName={progressBarIcon ? progressBarIcon : "FilePdf_SGDS"} size={24} colour="#565A5C" />}
              </div>
              <div className="file-details">
                <div className="file-name">{item.file.name}</div>
                <div className="file-meta">
                  {(item.file.size / (1024 * 1024)).toFixed(2)}MB <span className="file-meta-separator">&nbsp; &bull; &nbsp;</span>
                  {progress !== undefined ? (() => {
                    const currentProgress = typeof progress === "object"
                      ? (progress[item.fileId] ?? 0)
                      : (typeof progress === "number" ? progress : 0);
                    return currentProgress === 100 ? (
                      <span>{uploadSucessMessage ?? "Upload Completed"}</span>
                    ) : (
                      <span>Uploading: {currentProgress}%</span>
                    );
                  })() : (
                    <span>{uploadSucessMessage ?? "Upload Completed"}</span>
                  )}
                </div>

              </div>
              <div className="delete-icon" onClick={() => handleDelete(index)}>
                {<MpaIcon iconName="Trash" size={20} />}
              </div>
            </div>

            <div className="progress-bar-file">
              {progress !== undefined ? (() => {
                const currentProgress = typeof progress === "object"
                  ? (progress[item.fileId] ?? 0)
                  : (typeof progress === "number" ? progress : 0);
                // If progress is 100%, show green "Uploaded" state without progress bar animation
                if (currentProgress === 100) {
                  return (
                    <LinearLoader
                      id={`linear_loader_${item.fileId}`}
                      colour="var(--mpa-green)"
                      progress={100}
                      showProgress={false}
                      bar_width="100%"
                    />
                  );
                }
                // Otherwise show progress bar
                return (
                  <LinearLoader
                    id={`linear_loader_${item.fileId}`}
                    colour={loaderColour}
                    progress={currentProgress}
                    showProgress={false}
                    bar_width="100%"
                  />
                );
              })() : (
                <LinearLoader
                  id={`linear_loader_${item.fileId}`}
                  colour="var(--mpa-green)"
                  progress={100}
                  showProgress={false}
                  bar_width="100%"
                />
              )}
            </div>

          </div>
        )
      ))}
    </div>
  );
};

export default FileUpload;